const RISK_LEVELS = [
  { id: "solid", label: "סולידי", exposure: 10 },
  { id: "meuzan", label: "מאוזן", exposure: 40 },
  { id: "menayoti", label: "מנייתי", exposure: 80 },
];

const RETIREMENT_AGE_BY_GENDER = { male: 67, female: 65 };
const CONTRIBUTION_RATE = 0.2083;
const PENSION_FUND_FACTOR = 200;
const DEFAULT_FACTOR = 200;
const EQUITY_RATE = 0.075;
const BOND_RATE = 0.045;
const CASH_REAL_RATE = -0.025;
const OLD_AGE_BENEFIT = 2600;
const EARLY_RETIREMENT_TARGET_RATIO = 0.85;
const GAP_CRITICAL = 40;
const GAP_MODERATE = 20;
const GAP_NEGLIGIBLE = 5; // פער (בכל כיוון) שקטן מדי כדי לתאר אותו כ"קפיצה" או "חיתוך"
const BENCHMARK_DEVIATION = 15;
const SHORT_HORIZON_YEARS = 5;
// דמי ניהול שנתיים מהצבירה, מוערכים עבור ביטוחי מנהלים (לא נכללים בשאר המוצרים – ראו רשימת המגבלות).
const EXEC_MGMT_FEE = 0.008;
// Google Apps Script webhook endpoint that appends each submitted lead (contact info + exact
// calculator inputs) as a new row in the connected Google Sheet.
const WEBHOOK_URL =
  "https://script.google.com/macros/s/AKfycbwFhlYaO8qtjcpOCICIpSLRxFfbYgo4WHvJDbYhCUF_LkmbbrqiUOmxxdxCIvUw4KrGpg/exec";

function formatILS(num) {
  return Math.round(num).toLocaleString("he-IL");
}

// Used for figures the tool itself computed/estimated (already prefixed with "כ-" in the copy) —
// rounding to the nearest 100 avoids implying false precision the underlying model can't support.
// Exact user-entered amounts (salary, cash typed in, etc.) should keep using formatILS instead.
function formatILSApprox(num) {
  return formatILS(Math.round(num / 100) * 100);
}

function exposureToRate(exposurePct) {
  const e = Math.max(0, Math.min(100, exposurePct)) / 100;
  return e * EQUITY_RATE + (1 - e) * BOND_RATE;
}

function benchmarkExposure(years) {
  if (years > 10) return 100;
  if (years >= 5) return 70;
  if (years >= 2) return 40;
  return 15;
}

function resolveExposureAndRate(holding) {
  const riskConfig = RISK_LEVELS.find((r) => r.id === holding.risk) || RISK_LEVELS[1];
  const exposure = holding.exposure !== "" ? Number(holding.exposure) : riskConfig.exposure;
  return { exposure, rate: exposureToRate(exposure) };
}

// Future value of a level annual contribution, growing at `rate` for `yrs` years.
function annuityFV(annualAmount, rate, yrs) {
  const g = Math.pow(1 + rate, yrs);
  return rate > 0 ? annualAmount * ((g - 1) / rate) : annualAmount * yrs;
}

// Amount-weighted average real rate of return across a set of holdings, or null if the
// holdings carry no capital yet (e.g. a brand-new, still-empty account).
function weightedRateOf(holdings) {
  const amountSum = holdings.reduce((s, h) => s + (Number(h.amount) || 0), 0);
  if (amountSum <= 0) return null;
  let weighted = 0;
  holdings.forEach((h) => {
    const amount = Number(h.amount) || 0;
    const { rate } = resolveExposureAndRate(h);
    weighted += amount * rate;
  });
  return weighted / amountSum;
}
const DEFAULT_CONTRIBUTION_RATE = exposureToRate(RISK_LEVELS[1].exposure); // ברירת מחדל: מסלול "מאוזן"

function makeHolding(extra) {
  return { amount: "", risk: "", exposure: "", assetLabel: "", ...extra };
}

// מחשב את מקדם ההמרה לקצבה של ביטוח מנהלים: לפי מקדם ידוע שהוזן, או לפי שנת תחילת
// עבודה רציפה (כאשר המשתמש לא יודע את המקדם המדויק שלו).
function getExecutiveFactor(holding, gender) {
  if (holding.factorMode === "unknown") {
    const year = Number(holding.startYear) || 0;
    if (year > 0 && year < 2003) return gender === "female" ? 177 : 157;
    if (year >= 2003 && year <= 2013) return 200;
    if (year > 2013) return 220;
    return DEFAULT_FACTOR;
  }
  const known = Number(holding.knownFactor);
  return known > 0 ? known : DEFAULT_FACTOR;
}

export default function PensionGapCalculator() {
  const nextId = useRef(1);
  const newId = () => nextId.current++;

  const [age, setAge] = useState("");
  const [gender, setGender] = useState("female");
  const [salary, setSalary] = useState("");

  // --- Progressive-disclosure entry flow ---
  // "fast": only age/gender/salary + optional accumulation estimate, two-button fork.
  // "detailed": the full toggle cards (pension/executive/savings/cash) are revealed.
  const [entryStage, setEntryStage] = useState("fast");
  const [accumulationEstimate, setAccumulationEstimate] = useState("");
  const [fastTrackRisk, setFastTrackRisk] = useState("");
  const [fastAdditionalSavings, setFastAdditionalSavings] = useState("");
  const [fastSavingsRisk, setFastSavingsRisk] = useState("");
  const [earlyLeadOpen, setEarlyLeadOpen] = useState(false); // "escape hatch" in the detailed stage

  const [pensionFundOn, setPensionFundOn] = useState(false);
  const [pensionFundHoldings, setPensionFundHoldings] = useState([]);

  const [executiveOn, setExecutiveOn] = useState(false);
  const [executiveHoldings, setExecutiveHoldings] = useState([]);

  const [savingsOn, setSavingsOn] = useState(false);
  const [savingsHoldings, setSavingsHoldings] = useState([]);

  const [cashOn, setCashOn] = useState(false);
  const [cashAmount, setCashAmount] = useState("");
  const [contributionDestination, setContributionDestination] = useState("");

  const [submitted, setSubmitted] = useState(false);
  const [calculating, setCalculating] = useState(false);
  const [barWidth, setBarWidth] = useState(0);
  const [barColor, setBarColor] = useState(PURPLE);
  const [calcStepIndex, setCalcStepIndex] = useState(0);
  const [seenCardIndices, setSeenCardIndices] = useState(() => new Set());
  const [leadName, setLeadName] = useState("");
  const [leadPhone, setLeadPhone] = useState("");
  const [leadConsent, setLeadConsent] = useState(false);
  const [leadSubmitted, setLeadSubmitted] = useState(false);
  const [leadSubmitting, setLeadSubmitting] = useState(false);
  const [leadError, setLeadError] = useState(false);
  const [submitHover, setSubmitHover] = useState(false);
  const [showFastTooltip, setShowFastTooltip] = useState(false);
  const [shakeButton, setShakeButton] = useState(false);
  const [showErrors, setShowErrors] = useState(false);
  const noteCardRefs = useRef([]);

  // --- Iframe auto-resize ---
  // When embedded (e.g. via <iframe> in Elementor), the parent page has no way to know how
  // tall this widget's content is at any given moment — it changes a lot as the user moves
  // through the form, sees the calculating animation, then the results + note cards + lead
  // form. So on every layout-affecting change we measure the document's actual height and
  // postMessage it to window.parent; the snippet on the WordPress side listens for that
  // message and resizes the <iframe> to match. This is a no-op (harmless) when the page is
  // opened standalone, not inside an iframe.
  useEffect(() => {
    const sendHeightToParent = () => {
      const height = Math.max(document.documentElement.scrollHeight, document.body.scrollHeight);
      window.parent.postMessage({ source: "pension-gap-calculator", type: "resize", height }, "*");
    };

    sendHeightToParent();

    // Catches size changes (e.g. a card animating in, a note list growing/shrinking).
    const resizeObserver = new ResizeObserver(() => sendHeightToParent());
    resizeObserver.observe(document.body);

    // Catches DOM changes that don't always fire ResizeObserver in the same tick (nodes being
    // added/removed, attribute-driven style changes, text updates).
    const mutationObserver = new MutationObserver(() => sendHeightToParent());
    mutationObserver.observe(document.body, {
      childList: true,
      subtree: true,
      attributes: true,
      characterData: true,
    });

    // Safety net for changes neither observer catches in time — web font swap-in (Rubik loads
    // async), image decode, or the calculating→submitted transition's own timers.
    const intervalId = setInterval(sendHeightToParent, 500);

    window.addEventListener("resize", sendHeightToParent);

    return () => {
      resizeObserver.disconnect();
      mutationObserver.disconnect();
      clearInterval(intervalId);
      window.removeEventListener("resize", sendHeightToParent);
    };
  }, []);

  const retirementAge = RETIREMENT_AGE_BY_GENDER[gender];

  const isLeadFormValid = leadName.trim() !== "" && leadPhone.trim() !== "" && leadConsent === true;

  const handleLeadSubmit = async (honeypotValue) => {
    if (!isLeadFormValid || leadSubmitting) return;

    // Honeypot spam protection: if the bot filled the hidden field, silently abort.
    if (honeypotValue && honeypotValue !== "") {
      setLeadSubmitted(true);
      return;
    }

    setLeadSubmitting(true);
    setLeadError(false);

    try {
      await fetch(WEBHOOK_URL, {
        method: "POST",
        mode: "no-cors",
        headers: {
          "Content-Type": "text/plain;charset=utf-8"
        },
        body: JSON.stringify({
          // Contact Info
          name: leadName,
          phone: leadPhone,
          track: entryStage,

          // Base Inputs
          age: age,
          gender: gender,
          salary: salary,

          // Detailed Track Inputs
          pensionHoldings: pensionFundOn ? pensionFundHoldings : [],
          executiveHoldings: executiveOn ? executiveHoldings : [],
          savingsHoldings: savingsOn ? savingsHoldings : [],
          cashAmount: cashOn ? cashAmount : "",
          contributionDestination: contributionDestination,

          // Fast Track Inputs
          accumulationEstimate: entryStage === "fast" ? accumulationEstimate : "",
          fastTrackRisk: entryStage === "fast" ? fastTrackRisk : "",
          fastAdditionalSavings: entryStage === "fast" ? fastAdditionalSavings : "",
          fastSavingsRisk: entryStage === "fast" ? fastSavingsRisk : ""
        }),
      });

      // With no-cors, we can't read the response, so we assume success if no network error occurred.
      setLeadSubmitted(true);
    } catch (err) {
      setLeadError(true);
    } finally {
      setLeadSubmitting(false);
    }
  };

  const toggleCategory = (isOn, setOn, holdings, setHoldings, holdingFactory) => {
    const next = !isOn;
    setOn(next);
    if (next && holdings.length === 0) setHoldings([holdingFactory()]);
  };

  const addHolding = (setHoldings, factory) => setHoldings((h) => [...h, factory()]);
  const removeHolding = (setHoldings, id) => setHoldings((h) => h.filter((x) => x.id !== id));
  const updateHolding = (setHoldings, id, patch) =>
    setHoldings((h) => h.map((x) => (x.id === id ? { ...x, ...patch } : x)));

  const allHoldingAmountsNonNegative = [
    ...pensionFundHoldings,
    ...executiveHoldings,
    ...savingsHoldings,
  ].every((h) => h.amount === "" || Number(h.amount) >= 0);
  const allExposuresInRange = [...pensionFundHoldings, ...executiveHoldings, ...savingsHoldings].every(
    (h) => h.exposure === "" || (Number(h.exposure) >= 0 && Number(h.exposure) <= 100)
  );

  const fastTrackValid =
    accumulationEstimate !== "" &&
    Number(accumulationEstimate) >= 0 &&
    fastTrackRisk !== "" &&
    (fastAdditionalSavings === "" || (Number(fastAdditionalSavings) >= 0 && fastSavingsRisk !== ""));

  const detailedRiskValid =
    (!pensionFundOn || pensionFundHoldings.every((h) => h.risk !== "")) &&
    (!executiveOn || executiveHoldings.every((h) => h.risk !== "")) &&
    (!savingsOn || savingsHoldings.every((h) => h.risk !== "")) &&
    (!pensionFundOn || !executiveOn || contributionDestination !== "") &&
    (!savingsOn ||
      savingsHoldings.every((h) => !SAVINGS_TYPES_WITH_MANAGER.includes(h.assetLabel) || h.managedBy !== ""));

  const inputsValid =
    age !== "" &&
    salary !== "" &&
    Number(age) > 0 &&
    Number(age) < retirementAge &&
    Number(salary) > 0 &&
    (entryStage === "fast" ? fastTrackValid : true) &&
    (entryStage === "detailed" ? detailedRiskValid : true) &&
    (!pensionFundOn || pensionFundHoldings.every((h) => h.amount !== "")) &&
    (!executiveOn ||
      executiveHoldings.every(
        (h) =>
          h.amount !== "" &&
          (h.factorMode === "unknown"
            ? h.startYear !== "" && Number(h.startYear) > 0
            : h.knownFactor !== "" && Number(h.knownFactor) > 0)
      )) &&
    (!savingsOn || savingsHoldings.every((h) => h.amount !== "")) &&
    (!cashOn || (cashAmount !== "" && Number(cashAmount) >= 0)) &&
    allHoldingAmountsNonNegative &&
    allExposuresInRange;

  const result = useMemo(() => {
    if (!inputsValid) return null;

    const ageNum = Number(age);
    const salaryNum = Number(salary);
    const years = retirementAge - ageNum;

    const isEstimatedMode = !pensionFundOn && !executiveOn && !savingsOn && !cashOn;

    let activePensionHoldings = pensionFundOn ? pensionFundHoldings : [];
    const activeExecutiveHoldings = executiveOn ? executiveHoldings : [];
    let activeSavingsHoldings = savingsOn ? savingsHoldings : [];
    const cashNum = cashOn ? Number(cashAmount) || 0 : 0;

    if (isEstimatedMode) {
      // Fast Track: the user gives a real ballpark accumulation and risk level directly —
      // no more backward-reconstructed "saving continuously since age 24" fallback.
      activePensionHoldings = [
        { amount: String(Number(accumulationEstimate) || 0), risk: fastTrackRisk, exposure: "", assetLabel: "" },
      ];
      if (fastAdditionalSavings && Number(fastAdditionalSavings) > 0) {
        activeSavingsHoldings = [
          { amount: String(Number(fastAdditionalSavings)), risk: fastSavingsRisk, exposure: "", assetLabel: "FastTrackSavings" },
        ];
      }
    }

    let monthlyFromExisting = 0;
    let weightedExposureSum = 0;
    let weightedAmountSum = 0;

    activePensionHoldings.forEach((h) => {
      const amount = Number(h.amount) || 0;
      const { rate, exposure } = resolveExposureAndRate(h);
      const fv = amount * Math.pow(1 + rate, years);
      monthlyFromExisting += fv / PENSION_FUND_FACTOR;
      weightedExposureSum += amount * exposure;
      weightedAmountSum += amount;
    });

    activeExecutiveHoldings.forEach((h) => {
      const amount = Number(h.amount) || 0;
      const { rate, exposure } = resolveExposureAndRate(h);
      const factor = getExecutiveFactor(h, gender);
      const netRate = rate - EXEC_MGMT_FEE;
      const fv = amount * Math.pow(1 + netRate, years);
      monthlyFromExisting += fv / factor;
      weightedExposureSum += amount * exposure;
      weightedAmountSum += amount;
    });

    activeSavingsHoldings.forEach((h) => {
      const amount = Number(h.amount) || 0;
      const { rate, exposure } = resolveExposureAndRate(h);
      const fv = amount * Math.pow(1 + rate, years);
      monthlyFromExisting += fv / DEFAULT_FACTOR;
      weightedExposureSum += amount * exposure;
      weightedAmountSum += amount;
    });

    if (cashNum > 0) {
      const fv = cashNum * Math.pow(1 + CASH_REAL_RATE, years);
      monthlyFromExisting += fv / DEFAULT_FACTOR;
      weightedAmountSum += cashNum;
    }

    // When there's an active executive-insurance policy — either as the only pension vehicle,
    // or as the chosen destination when a pension fund also exists — ongoing contributions are
    // annuitized using its real (weighted) conversion factor instead of the generic 200, and
    // their growth carries the same 0.8% management fee as the rest of that product.
    const contributesToExecutive = executiveOn && (!pensionFundOn || contributionDestination === "executive");

    let contributionFactor = PENSION_FUND_FACTOR;
    const execAmount = activeExecutiveHoldings.reduce((s, h) => s + (Number(h.amount) || 0), 0);
    if (contributesToExecutive) {
      if (execAmount > 0) {
        let weightedFactor = 0;
        activeExecutiveHoldings.forEach((h) => {
          const amount = Number(h.amount) || 0;
          const factor = getExecutiveFactor(h, gender);
          weightedFactor += amount * factor;
        });
        contributionFactor = weightedFactor / execAmount;
      } else {
        // Fallback if toggled on but empty amount: use the default factor.
        contributionFactor = DEFAULT_FACTOR;
      }
    }

    // Growth rate for *new* ongoing deposits: based on where they're actually invested
    // (contributionDestination), never on the risk mix of capital already accumulated elsewhere.
    const contributionGrowthRate = contributesToExecutive
      ? (weightedRateOf(activeExecutiveHoldings) ?? DEFAULT_CONTRIBUTION_RATE) - EXEC_MGMT_FEE
      : weightedRateOf(activePensionHoldings) ?? DEFAULT_CONTRIBUTION_RATE;

    const annualContribution = salaryNum * 12 * CONTRIBUTION_RATE;
    const monthlyFromContributions = annuityFV(annualContribution, contributionGrowthRate, years) / contributionFactor;

    const monthlyIncome = monthlyFromExisting + monthlyFromContributions + OLD_AGE_BENEFIT;
    const gapPercent = ((salaryNum - monthlyIncome) / salaryNum) * 100;
    const gapAmount = salaryNum - monthlyIncome;

    const blendedExposure = weightedAmountSum > 0 ? weightedExposureSum / weightedAmountSum : 0;
    const benchmark = benchmarkExposure(years);
    const isGreenScenario = gapPercent < GAP_MODERATE;

    // Early retirement — optimal-exposure simulation (fees not modeled; see note in UI).
    // Withdrawing from a pension fund or executive insurance before age 60 is taxed very heavily,
    // so an age below 60 is only accepted if BOTH hold: (1) non-pension savings + cash can bridge
    // the income until 60, drawn down to exactly zero by then, and (2) the pension capital alone —
    // grown with no further contributions after the early-retirement age, then annuitized at 60 via
    // its real conversion factor — still reaches the target on its own from 60 onward. Otherwise
    // there would be a cliff in income right at 60 when the bridge runs out.
    const EARLY_WITHDRAWAL_AGE_FLOOR = 60;
    let earlyRetirementAge = null;
    for (let a = ageNum + 1; a < retirementAge; a++) {
      const yrs = a - ageNum;
      const optimalRate = exposureToRate(benchmarkExposure(yrs));
      let monthlyE = 0;
      let meetsTarget = false;

      if (a < EARLY_WITHDRAWAL_AGE_FLOOR) {
        const yearsToSixty = EARLY_WITHDRAWAL_AGE_FLOOR - a;
        const rateAfterRetiring = exposureToRate(benchmarkExposure(yearsToSixty));

        // (1) Bridge: non-pension savings + cash grown to age a, then drawn down to zero by 60.
        // Fast Track's "additional savings" field is now injected into activeSavingsHoldings
        // itself (see isEstimatedMode block above), so it's already included in this loop.
        let bridgeCapital = 0;
        activeSavingsHoldings.forEach((h) => {
          const amount = Number(h.amount) || 0;
          bridgeCapital += amount * Math.pow(1 + optimalRate, yrs);
        });
        if (cashNum > 0) {
          bridgeCapital += cashNum * Math.pow(1 + optimalRate, yrs);
        }
        const bridgeMonths = yearsToSixty * 12;
        const bridgeMonthlyRate = Math.pow(1 + rateAfterRetiring, 1 / 12) - 1;
        const bridgeMonthlyIncome =
          bridgeMonthlyRate > 0
            ? (bridgeCapital * bridgeMonthlyRate) / (1 - Math.pow(1 + bridgeMonthlyRate, -bridgeMonths))
            : bridgeCapital / bridgeMonths;

        // (2) Pension capital alone, with contributions stopping at the early-retirement age,
        // then just growing (no more deposits) until 60, annuitized at 60 via the real factor.
        let pensionOnlyMonthlyAt60 = 0;
        activePensionHoldings.forEach((h) => {
          const amount = Number(h.amount) || 0;
          const valueAtA = amount * Math.pow(1 + optimalRate, yrs);
          const valueAt60 = valueAtA * Math.pow(1 + rateAfterRetiring, yearsToSixty);
          pensionOnlyMonthlyAt60 += valueAt60 / PENSION_FUND_FACTOR;
        });
        activeExecutiveHoldings.forEach((h) => {
          const amount = Number(h.amount) || 0;
          const factor = getExecutiveFactor(h, gender);
          const netOptimalRate = optimalRate - EXEC_MGMT_FEE;
          const netRateAfterRetiring = rateAfterRetiring - EXEC_MGMT_FEE;
          const valueAtA = amount * Math.pow(1 + netOptimalRate, yrs);
          const valueAt60 = valueAtA * Math.pow(1 + netRateAfterRetiring, yearsToSixty);
          pensionOnlyMonthlyAt60 += valueAt60 / factor;
        });
        const contributionRateAtOptimal = contributesToExecutive ? optimalRate - EXEC_MGMT_FEE : optimalRate;
        const netRateAfterRetiringForContrib = contributesToExecutive
          ? rateAfterRetiring - EXEC_MGMT_FEE
          : rateAfterRetiring;
        const fvContribAt60 =
          annuityFV(annualContribution, contributionRateAtOptimal, yrs) *
          Math.pow(1 + netRateAfterRetiringForContrib, yearsToSixty);
        pensionOnlyMonthlyAt60 += fvContribAt60 / contributionFactor;

        monthlyE = bridgeMonthlyIncome; // reported figure while the bridge is active
        meetsTarget =
          bridgeMonthlyIncome / salaryNum >= EARLY_RETIREMENT_TARGET_RATIO &&
          pensionOnlyMonthlyAt60 / salaryNum >= EARLY_RETIREMENT_TARGET_RATIO;
      } else {
        activePensionHoldings.forEach((h) => {
          const amount = Number(h.amount) || 0;
          monthlyE += (amount * Math.pow(1 + optimalRate, yrs)) / PENSION_FUND_FACTOR;
        });
        activeExecutiveHoldings.forEach((h) => {
          const amount = Number(h.amount) || 0;
          const factor = getExecutiveFactor(h, gender);
          const netOptimalRate = optimalRate - EXEC_MGMT_FEE;
          monthlyE += (amount * Math.pow(1 + netOptimalRate, yrs)) / factor;
        });
        activeSavingsHoldings.forEach((h) => {
          const amount = Number(h.amount) || 0;
          monthlyE += (amount * Math.pow(1 + optimalRate, yrs)) / DEFAULT_FACTOR;
        });
        if (cashNum > 0) {
          monthlyE += (cashNum * Math.pow(1 + optimalRate, yrs)) / DEFAULT_FACTOR;
        }
        const contributionRateAtOptimal = contributesToExecutive ? optimalRate - EXEC_MGMT_FEE : optimalRate;
        monthlyE += annuityFV(annualContribution, contributionRateAtOptimal, yrs) / contributionFactor;
        meetsTarget = monthlyE / salaryNum >= EARLY_RETIREMENT_TARGET_RATIO;
      }

      if (meetsTarget) {
        earlyRetirementAge = a;
        break;
      }
    }

    // --- Total accumulated capital: current track vs. an optimally-exposed track ---
    const benchmarkRate = exposureToRate(benchmark);
    let capitalActual = 0;
    let capitalOptimal = 0;
    [...activePensionHoldings, ...activeSavingsHoldings].forEach((h) => {
      const amount = Number(h.amount) || 0;
      const { rate } = resolveExposureAndRate(h);
      capitalActual += amount * Math.pow(1 + rate, years);
      capitalOptimal += amount * Math.pow(1 + benchmarkRate, years);
    });
    activeExecutiveHoldings.forEach((h) => {
      const amount = Number(h.amount) || 0;
      const { rate } = resolveExposureAndRate(h);
      const netRate = rate - EXEC_MGMT_FEE;
      const netBenchmarkRate = benchmarkRate - EXEC_MGMT_FEE;
      capitalActual += amount * Math.pow(1 + netRate, years);
      capitalOptimal += amount * Math.pow(1 + netBenchmarkRate, years);
    });
    if (cashNum > 0) {
      // Actual: cash keeps eroding at -2.5% real, uninvested. Optimal: invested at the benchmark exposure.
      capitalActual += cashNum * Math.pow(1 + CASH_REAL_RATE, years);
      capitalOptimal += cashNum * Math.pow(1 + benchmarkRate, years);
    }
    const contributionRateOptimal = contributesToExecutive ? benchmarkRate - EXEC_MGMT_FEE : benchmarkRate;
    const fvContribActual = annuityFV(annualContribution, contributionGrowthRate, years);
    const fvContribOptimal = annuityFV(annualContribution, contributionRateOptimal, years);
    capitalActual += fvContribActual;
    capitalOptimal += fvContribOptimal;
    const capitalGap = Math.max(capitalOptimal - capitalActual, 0);

    // Monthly income if the whole portfolio were at the benchmark exposure (used both for the
    // "conservative track" flag and for the closing line of the main sentence).
    let monthlyAtBenchmark = 0;
    activePensionHoldings.forEach((h) => {
      const amount = Number(h.amount) || 0;
      monthlyAtBenchmark += (amount * Math.pow(1 + benchmarkRate, years)) / PENSION_FUND_FACTOR;
    });
    activeExecutiveHoldings.forEach((h) => {
      const amount = Number(h.amount) || 0;
      const factor = getExecutiveFactor(h, gender);
      const netBenchmarkRate = benchmarkRate - EXEC_MGMT_FEE;
      monthlyAtBenchmark += (amount * Math.pow(1 + netBenchmarkRate, years)) / factor;
    });
    activeSavingsHoldings.forEach((h) => {
      const amount = Number(h.amount) || 0;
      monthlyAtBenchmark += (amount * Math.pow(1 + benchmarkRate, years)) / DEFAULT_FACTOR;
    });
    monthlyAtBenchmark += annuityFV(annualContribution, contributionRateOptimal, years) / contributionFactor;
    monthlyAtBenchmark += OLD_AGE_BENEFIT;

    const notes = [];
    let hasExplicitExposureData = false;

    if (!isEstimatedMode) {
      // The 80% default for "מנייתי" is an assumption you're not confident in — so any holding
      // relying on it (risk = menayoti, no explicit exposure typed in) makes the exposure-mismatch
      // comparison unreliable. Holdings defaulting to "מאוזן" or "סולידי" are fine to use as-is.
    const hasUnreliableEquityDefault = [
      ...activePensionHoldings,
      ...activeExecutiveHoldings,
      ...activeSavingsHoldings,
    ].some((h) => h.exposure === "" && h.risk === "menayoti");
    hasExplicitExposureData = !hasUnreliableEquityDefault;

    // Which categories are individually dragging the blended exposure below the benchmark —
    // used to name the specific instrument(s) in the "conservative track" card instead of a
    // generic "your portfolio".
    function categoryExposure(holdings) {
      let amountSum = 0;
      let exposureSum = 0;
      holdings.forEach((h) => {
        const amount = Number(h.amount) || 0;
        const { exposure } = resolveExposureAndRate(h);
        amountSum += amount;
        exposureSum += amount * exposure;
      });
      return amountSum > 0 ? exposureSum / amountSum : null;
    }
    const categoryLabels = [];
    const pensionExp = categoryExposure(activePensionHoldings);
    if (pensionExp !== null && pensionExp < benchmark - BENCHMARK_DEVIATION) categoryLabels.push("קרן הפנסיה");
    const executiveExp = categoryExposure(activeExecutiveHoldings);
    if (executiveExp !== null && executiveExp < benchmark - BENCHMARK_DEVIATION) categoryLabels.push("ביטוח המנהלים");
    const savingsExp = categoryExposure(activeSavingsHoldings);
    if (savingsExp !== null && savingsExp < benchmark - BENCHMARK_DEVIATION)
      categoryLabels.push("החיסכון וההשקעות הנזילות");
    let conservativeSourceLabel = "בתיק שלכם";
    if (categoryLabels.length === 1) conservativeSourceLabel = `ב${categoryLabels[0]}`;
    else if (categoryLabels.length === 2) conservativeSourceLabel = `ב${categoryLabels[0]} וב${categoryLabels[1]}`;
    else if (categoryLabels.length >= 3)
      conservativeSourceLabel = `ב${categoryLabels[0]}, ב${categoryLabels[1]} וב${categoryLabels[2]}`;

    // --- Portfolio-wide "money working too conservatively" check (used in both scenarios) ---
    // Only shown when at least one holding has a real, user-entered exposure figure — otherwise
    // the whole comparison rests on assumed defaults and shouldn't be presented as a finding.
    if (hasExplicitExposureData && weightedAmountSum > 0 && blendedExposure < benchmark - BENCHMARK_DEVIATION) {
      const potentialGain = Math.max(monthlyAtBenchmark - monthlyIncome, 0);

      if (!isGreenScenario) {
        notes.push({
          type: "warning",
          icon: <ShieldAlert size={18} color={WARNING_TEXT} />,
          title: "חשיפה שמרנית מדי",
          bigNumber: `₪${formatILSApprox(potentialGain)}+`,
          text: `זהו פוטנציאל הקצבה החודשית שאתם מוותרים עליו. מסלול ההשקעה ${conservativeSourceLabel} סולידי מדי ביחס לזמן שנותר לכם עד הפרישה. התאמת רמת הסיכון למשך תקופת החיסכון היא קריטית כדי לעזור לסגור את הפער שנוצר.`,
          impact: potentialGain,
        });
      } else {
        notes.push({
          type: "positive",
          icon: <Sparkles size={18} color={POSITIVE} />,
          title: "אפשר להוציא מהתיק יותר",
          bigNumber: `₪${formatILSApprox(potentialGain)}+`,
          text: `זהו הסכום הנוסף שיכולתם לקבל בכל חודש בפרישה. למרות שתמונת הפרישה שלכם נראית טוב, התאמת המסלול ${conservativeSourceLabel} לזמן שנותר יכולה לשדרג משמעותית את רמת החיים שלכם מעבר לציפיות, ללא שינוי בהפקדות.`,
          impact: potentialGain,
        });
      }
    } else if (
      hasExplicitExposureData &&
      !isGreenScenario &&
      weightedAmountSum > 0 &&
      years < SHORT_HORIZON_YEARS &&
      blendedExposure > benchmark + BENCHMARK_DEVIATION
    ) {
      notes.push({
        type: "warning",
        icon: <ShieldAlert size={18} color={WARNING_TEXT} />,
        title: "חשיפת יתר סמוך לפרישה",
        bigNumber: `${years} שנים`,
        text: `זה כל הזמן שנותר לכם עד הפרישה, אך הוא אינו תואם את פרופיל הסיכון הגבוה של התיק כיום. ניהול סיכונים מקצועי דורש הפחתה הדרגתית של החשיפה למניות לקראת מועד הפרישה, כדי למנוע זעזועים בלתי הפיכים בערך הקצבה.`,
        impact: weightedAmountSum * 0.1,
      });
    }

    if (cashOn && cashNum > 0) {
      const cashCumulativeErosion = cashNum - cashNum * Math.pow(1 + CASH_REAL_RATE, years);
      notes.push({
        type: "critical",
        icon: <Banknote size={18} color={CRITICAL} />,
        title: "שחיקת כסף במזומן",
        bigNumber: `₪${formatILSApprox(cashCumulativeErosion)}-`,
        text: `זהו אובדן הערך הצפוי של ה-₪${formatILS(cashNum)} שיושבים כרגע בעובר ושב ללא השקעה. כסף שלא צובר תשואה נשחק בהדרגה מול האינפלציה, ועד גיל הפרישה הפגיעה בכוח הקנייה שלו תהיה משמעותית.`,
        impact: cashCumulativeErosion,
      });
    }

    const bankHoldings = activeSavingsHoldings.filter((h) => h.managedBy === "bank");
    if (bankHoldings.length > 0) {
      notes.push({
        type: "warning",
        icon: <Landmark size={18} color={WARNING_TEXT} />,
        title: "חיסכון יקר דרך הבנק",
        text: `מודל התמחור הבנקאי מבוסס על עמלות מסחר ודמי משמרת שנוגסים באופן עקבי בתשואה שלכם, במקום שהכסף ינוהל בשקיפות וביעילות בפלטפורמות פיננסיות מודרניות. לאורך זמן, העלויות האלו עלולות לפגוע משמעותית בפוטנציאל הצמיחה של הכסף.`,
        impact: 1,
      });
    }

    // Group by factor category first, so a user with several policies of the same kind sees
    // one aggregated note instead of an identical card repeated once per policy.
    const goodFactorHoldings = activeExecutiveHoldings.filter((h) => getExecutiveFactor(h, gender) < 200);
    const otherFactorHoldings = activeExecutiveHoldings.filter((h) => getExecutiveFactor(h, gender) >= 200);

    if (goodFactorHoldings.length > 0) {
      const goodFactorAmount = goodFactorHoldings.reduce((s, h) => s + (Number(h.amount) || 0), 0);
      notes.push({
        type: "positive",
        icon: <Sparkles size={18} color={POSITIVE} />,
        title: "פוליסת מנהלים בעלת ערך",
        text: `הפוליסה הוותיקה שלכם אוצרת בתוכה יתרון פנסיוני משמעותי – הגנת מקדם. ההבטחה הזו מתורגמת לקצבה גבוהה ויציבה יותר עבור כל שקל שנחסך בה, ומהווה נכס שחובה לקחת בחשבון כשבוחנים את כדאיות דמי הניהול.`,
        impact: goodFactorAmount,
      });
      notes.push({
        type: "warning",
        icon: <FileWarning size={18} color={WARNING_TEXT} />,
        title: "דמי ניהול יקרים",
        text: `החזקת פוליסת מנהלים ותיקה מלווה לרוב בעלויות ניהול עודפות. כדי שהפוליסה באמת תשתלם, יש לוודא שהרווח העתידי מהמקדם המובטח גובר על השחיקה הוודאית של דמי הניהול לאורך שנות החיסכון.`,
        impact: goodFactorAmount,
      });
    }

    if (otherFactorHoldings.length > 0) {
      const otherFactorAmount = otherFactorHoldings.reduce((s, h) => s + (Number(h.amount) || 0), 0);
      notes.push({
        type: "warning",
        icon: <FileWarning size={18} color={WARNING_TEXT} />,
        title: "ביטוח מנהלים ללא הגנה",
        text: `ביטוחי מנהלים מהשנים האחרונות איבדו את היתרון המרכזי שלהם – הבטחת המקדם. נכון להיום, אתם משלמים דמי ניהול של מוצר פרימיום, אך מקבלים תנאים דומים מאוד למוצרים פנסיוניים זולים בהרבה.`,
        impact: otherFactorAmount,
      });
    }

    if (goodFactorHoldings.length > 0) {
      const oldAmount = goodFactorHoldings.reduce((s, h) => s + (Number(h.amount) || 0), 0);
      let oldPolicyMonthlyIncome = 0;
      goodFactorHoldings.forEach((h) => {
        const amount = Number(h.amount) || 0;
        const { rate } = resolveExposureAndRate(h);
        const factor = getExecutiveFactor(h, gender);
        const netRate = rate - EXEC_MGMT_FEE;
        oldPolicyMonthlyIncome += (amount * Math.pow(1 + netRate, years)) / factor;
      });
      const incomeFromOtherSources = monthlyIncome - oldPolicyMonthlyIncome;
      if (incomeFromOtherSources >= salaryNum) {
        notes.push({
          type: "warning",
          icon: <FileWarning size={18} color={WARNING_TEXT} />,
          title: "כפילות בביטוח הוותיק",
          text: `מצבכם הפנסיוני מצוין, מה שמעלה שאלה אסטרטגית: האם נכון להמשיך לשלם דמי ניהול יקרים על פוליסת המנהלים? כשהקצבה הבסיסית מובטחת ממקורות אחרים, שווה לבדוק אפשרות לייעל את התיק למוצרים חסכוניים יותר.`,
          impact: oldAmount,
        });
      }
    }


    if (earlyRetirementAge !== null) {
      notes.push({
        type: "positive",
        icon: <Sparkles size={18} color={POSITIVE} />,
        title: "אפשרות לפרישה מוקדמת",
        bigNumber: `גיל ${earlyRetirementAge}`,
        text: `זהו הגיל שבו תוכלו להרשות לעצמכם לפרוש ללא פגיעה ברמת החיים. עם בניית תיק נכונה היום והתאמת סיכונים, הנתונים מראים שתוכלו להפסיק לעבוד לפני גיל הפרישה הרשמי.`,
        impact: 0,
      });
    }
    } // end !isEstimatedMode

    notes.sort((a, b) => {
      const aGreen = a.type === "positive" ? 1 : 0;
      const bGreen = b.type === "positive" ? 1 : 0;
      if (aGreen !== bGreen) return aGreen - bGreen;
      return (b.impact || 0) - (a.impact || 0);
    });

    return {
      years,
      monthlyIncome,
      gapPercent,
      gapAmount,
      currentSalary: salaryNum,
      notes,
      isEstimatedMode,
      isGreenScenario,
      capitalActual,
      capitalOptimal,
      capitalGap,
      monthlyAtBenchmark,
      hasExplicitExposureData,
      earlyRetirementAge,
    };
  }, [
    age,
    salary,
    gender,
    retirementAge,
    pensionFundOn,
    pensionFundHoldings,
    executiveOn,
    executiveHoldings,
    savingsOn,
    savingsHoldings,
    cashOn,
    cashAmount,
    contributionDestination,
    accumulationEstimate,
    fastTrackRisk,
    fastAdditionalSavings,
    fastSavingsRisk,
    inputsValid,
  ]);

  const visibleNotes = result
    ? result.notes.filter((n) => n.title !== "אפשרות לפרישה מוקדמת")
    : [];

  const noteCount = visibleNotes.length;

  useEffect(() => {
    if (!submitted) return;
    setSeenCardIndices(new Set());
    const observer = new IntersectionObserver(
      (entries) => {
        setSeenCardIndices((prev) => {
          const next = new Set(prev);
          entries.forEach((entry) => {
            if (entry.isIntersecting) {
              const idx = Number(entry.target.dataset.cardIndex);
              next.add(idx);
            }
          });
          return next;
        });
      },
      { threshold: 0.6 }
    );
    noteCardRefs.current.forEach((el) => {
      if (el) observer.observe(el);
    });
    return () => observer.disconnect();
  }, [submitted, noteCount]);

  const reachedEnd = noteCount === 0 ? true : seenCardIndices.size >= noteCount;

  const heading =
    result == null
      ? ""
      : result.gapPercent >= GAP_CRITICAL
      ? "התראת פנסיה: זיהינו פער קריטי בהכנסה הצפויה"
      : result.gapPercent >= GAP_MODERATE
      ? "צפויה ירידה משמעותית ברמת החיים בפרישה"
      : "מצב פנסיוני תקין: רמת החיים שלכם תישמר";

  const CALC_STEPS = ["מנתחים את הצבירה...", "מחשבים הפקדות עתידיות...", "מחשבים את הקצבה החודשית...", "מרכיבים את תמונת המצב..."];
  const CALC_STEP_MS = 1500;
  const CALC_ANIMATION_MS = CALC_STEPS.length * CALC_STEP_MS;

  const handleCalculate = () => {
    if (!inputsValid || !result) return;
    setSubmitted(false);
    setCalculating(true);
    setBarWidth(0);
    setBarColor(PURPLE);
    setCalcStepIndex(0);
    const targetColor = result.gapPercent > 0 ? CRITICAL : POSITIVE;
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        setBarWidth(100);
        setBarColor(targetColor);
      });
    });
    let step = 0;
    const stepInterval = setInterval(() => {
      step += 1;
      if (step < CALC_STEPS.length) setCalcStepIndex(step);
    }, CALC_STEP_MS);
    setTimeout(() => {
      clearInterval(stepInterval);
      setCalculating(false);
      setSubmitted(true);
    }, CALC_ANIMATION_MS);
  };

  const handleAttemptSubmit = () => {
    if (!inputsValid) {
      setShowErrors(true);
      setShakeButton(true);
      setTimeout(() => setShakeButton(false), 400);
      // Wait a tick for the error-highlighted fields to actually render, then jump to
      // the topmost one so the user immediately sees what's still missing.
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          const firstError = document.querySelector('[data-error-field="true"]');
          if (firstError) firstError.scrollIntoView({ behavior: "smooth", block: "center" });
        });
      });
      return;
    }
    setShowErrors(false);
    handleCalculate();
  };

  return (
    <div
      dir="rtl"
      style={{
        fontFamily: "'Rubik', sans-serif",
        background: PAGE_BG,
        // No forced minHeight: "100vh" here on purpose. With it, an embedded iframe would
        // always report at least the visitor's full viewport height — even for the short
        // initial form — defeating the auto-resize below. Height now simply follows content.
        padding: "32px 16px",
        color: TEXT_MAIN,
        display: "flex",
        justifyContent: "center",
      }}
    >
      <style>{FONT_IMPORT}</style>
      <div style={{ width: "100%", maxWidth: 540 }}>
        <div style={{ textAlign: "center", marginBottom: 24 }}>
          <img src={LOGO_SRC} alt="Effectiv" style={{ height: 46, maxHeight: 46, width: "auto", margin: "0 auto 16px", display: "block" }} />
          <h1
            style={{
              fontWeight: 800,
              fontSize: 29,
              lineHeight: 1.4,
              margin: "0 auto",
              color: NAVY,
              maxWidth: 520,
            }}
          >
            {cfg.mainHeaders.hookMain}
          </h1>
          <p
            style={{
              fontWeight: 500,
              fontSize: 19,
              lineHeight: 1.5,
              margin: "8px auto 0",
              color: WARNING_TEXT,
              maxWidth: 420,
            }}
          >
            {cfg.mainHeaders.hookSub}
          </p>
          <p
            style={{
              color: TEXT_MUTED,
              fontSize: 15,
              lineHeight: 1.6,
              maxWidth: 480,
              margin: "12px auto 0",
            }}
          >
            {cfg.mainHeaders.subtitle}
          </p>
        </div>

        {!calculating && !submitted && (
          <div
            className="no-print"
            style={{ background: CARD_BG, borderRadius: 12, overflow: "hidden", boxShadow: "0 2px 16px rgba(30,42,92,0.08)" }}
          >
            <div style={{ background: GRADIENT, padding: "16px 20px", color: "#FFFFFF", fontWeight: 700, fontSize: 17, textAlign: "center" }}>
              {cfg.mainHeaders.title}
            </div>

          <div style={{ padding: 22, display: "flex", flexDirection: "column", gap: 18 }}>
            <div style={{ display: "flex", gap: 12 }}>
              <div style={{ flex: 1 }}>
                <Field label={cfg.baseInputs.age}>
                  <NumberInput value={age} onChange={(e) => setAge(e.target.value)} placeholder="לדוגמה: 45" style={inputStyle} error={showErrors && (age === "" || Number(age) <= 0 || Number(age) >= retirementAge)} />
                </Field>
              </div>
              <div style={{ flex: 1 }}>
                <Field label={cfg.baseInputs.genderLabel}>
                  <div style={{ display: "flex", gap: 8 }}>
                    <PillButton active={gender === "male"} onClick={() => setGender("male")}>
                      {cfg.baseInputs.genderMale}
                    </PillButton>
                    <PillButton active={gender === "female"} onClick={() => setGender("female")}>
                      {cfg.baseInputs.genderFemale}
                    </PillButton>
                  </div>
                </Field>
              </div>
            </div>

            <Field label={cfg.baseInputs.salary}>
              <NumberInput value={salary} onChange={(e) => setSalary(e.target.value)} placeholder="לדוגמה: 22,000" style={inputStyle} error={showErrors && (salary === "" || Number(salary) <= 0)} />
            </Field>

            {entryStage === "fast" && (
              <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                <Field label="סך הצבירה הפנסיונית הנוכחית">
                  <NumberInput
                    value={accumulationEstimate}
                    onChange={(e) => setAccumulationEstimate(e.target.value)}
                    placeholder="למשל 400,000"
                    style={inputStyle}
                    error={showErrors && (accumulationEstimate === "" || Number(accumulationEstimate) < 0)}
                  />
                </Field>
                {accumulationEstimate !== "" && (
                  <Field label={cfg.products.riskLabel}>
                    <PillGroup
                      options={RISK_LEVELS.map((r) => r.label)}
                      value={RISK_LEVELS.find((r) => r.id === fastTrackRisk)?.label}
                      onChange={(label) => setFastTrackRisk(RISK_LEVELS.find((r) => r.label === label).id)}
                      error={showErrors && fastTrackRisk === ""}
                    />
                  </Field>
                )}
                <Field label="חסכונות נוספים (השתלמות, גמל, פוליסות – סכום כולל)">
                  <NumberInput
                    value={fastAdditionalSavings}
                    onChange={(e) => setFastAdditionalSavings(e.target.value)}
                    placeholder="למשל 150,000"
                    style={inputStyle}
                    error={showErrors && fastAdditionalSavings !== "" && Number(fastAdditionalSavings) < 0}
                  />
                </Field>
                <div style={{ fontSize: 14, fontWeight: 600, color: NAVY, marginTop: -6, textAlign: "right" }}>
                  * לא זוכרים במדויק? הכל טוב. הערכה כללית תספיק כדי לתת לכם כיוון.
                </div>
                {fastAdditionalSavings !== "" && (
                  <div style={{ marginTop: 4 }}>
                    <Field label="מסלול השקעה (עבור החסכונות הנוספים)">
                      <PillGroup
                        options={RISK_LEVELS.map((r) => r.label)}
                        value={RISK_LEVELS.find((r) => r.id === fastSavingsRisk)?.label}
                        onChange={(label) => setFastSavingsRisk(RISK_LEVELS.find((r) => r.label === label).id)}
                        error={showErrors && fastSavingsRisk === ""}
                      />
                    </Field>
                  </div>
                )}
                <button
                  onClick={handleAttemptSubmit}
                  disabled={calculating}
                  className={shakeButton ? "shake" : ""}
                  style={{
                    padding: "14px",
                    borderRadius: 999,
                    border: "none",
                    background: inputsValid && !calculating ? PURPLE : "#D6D8E2",
                    color: "#FFFFFF",
                    fontFamily: "'Rubik', sans-serif",
                    fontWeight: 700,
                    fontSize: 16,
                    cursor: inputsValid && !calculating ? "pointer" : "not-allowed",
                  }}
                >
                  <div style={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 8, position: "relative" }}>
                    <span>לקבלת תמונת מצב מהירה</span>
                    <div
                      onMouseEnter={() => setShowFastTooltip(true)}
                      onMouseLeave={() => setShowFastTooltip(false)}
                      onClick={(e) => {
                        e.stopPropagation();
                        setShowFastTooltip(!showFastTooltip);
                      }}
                      style={{ display: "flex", alignItems: "center", cursor: "help" }}
                    >
                      <Info size={18} color="#FFFFFF" style={{ opacity: 0.8 }} />
                    </div>

                    {showFastTooltip && (
                      <div
                        style={{
                          position: "absolute",
                          bottom: "100%",
                          left: "50%",
                          transform: "translateX(-50%)",
                          marginBottom: 14,
                          background: "#242B45",
                          color: "#FFFFFF",
                          padding: "12px 16px",
                          borderRadius: 8,
                          fontSize: 13,
                          lineHeight: 1.5,
                          width: "max-content",
                          maxWidth: 280,
                          textAlign: "center",
                          boxShadow: "0 4px 12px rgba(30,42,92,0.2)",
                          zIndex: 50,
                          fontWeight: 400,
                          pointerEvents: "none",
                          whiteSpace: "normal",
                        }}
                      >
                        אנחנו משתמשים כאן בהנחות יסוד ממוצעות כדי לחסוך לכם זמן. אם יש לכם דקה פנויה, המחשבון
                        המורחב יפיק עבורכם ניתוח מדויק ואישי הרבה יותר.
                        <div
                          style={{
                            position: "absolute",
                            top: "100%",
                            left: "50%",
                            transform: "translateX(-50%)",
                            borderWidth: 6,
                            borderStyle: "solid",
                            borderColor: "#242B45 transparent transparent transparent",
                          }}
                        />
                      </div>
                    )}
                  </div>
                </button>
                <button
                  onClick={() => setEntryStage("detailed")}
                  style={{
                    padding: "14px",
                    borderRadius: 999,
                    border: `1.5px solid ${PURPLE}`,
                    background: "transparent",
                    color: PURPLE,
                    fontFamily: "'Rubik', sans-serif",
                    fontWeight: 700,
                    fontSize: 16,
                    cursor: "pointer",
                  }}
                >
                  רוצים תוצאה מדויקת ומותאמת אישית? פתחו את המחשבון המלא
                </button>
              </div>
            )}

            {entryStage === "detailed" && (
              <>
                <div>
                  <span style={{ fontSize: 13, color: TEXT_MUTED, display: "block", marginBottom: 4 }}>
                    אילו רכיבי חיסכון והשקעה קיימים ברשותכם?
                  </span>
                  <span style={{ fontSize: 12, color: TEXT_FAINT, display: "block", marginBottom: 10 }}>
                    {cfg.baseInputs.accuracyNote}
                  </span>
                  <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                    <ToggleCard
                      icon={<PiggyBank size={16} />}
                      label={cfg.products.pension.title}
                      checked={pensionFundOn}
                      onToggle={() =>
                        toggleCategory(pensionFundOn, setPensionFundOn, pensionFundHoldings, setPensionFundHoldings, () =>
                          makeHolding({ id: newId() })
                        )
                      }
                    >
                      {pensionFundHoldings.map((h) => (
                        <FundHoldingRow
                          key={h.id}
                          holding={h}
                          showRemove={pensionFundHoldings.length > 1}
                          onChange={(patch) => updateHolding(setPensionFundHoldings, h.id, patch)}
                          onRemove={() => removeHolding(setPensionFundHoldings, h.id)}
                          showErrors={showErrors}
                        />
                      ))}
                      <AddButton onClick={() => addHolding(setPensionFundHoldings, () => makeHolding({ id: newId() }))} label={cfg.products.pension.addMore} />
                    </ToggleCard>

                    <ToggleCard
                      icon={<FileWarning size={16} />}
                      label={cfg.products.execInsurance.title}
                      checked={executiveOn}
                      onToggle={() =>
                        toggleCategory(executiveOn, setExecutiveOn, executiveHoldings, setExecutiveHoldings, () =>
                          makeHolding({ id: newId(), factorMode: "known", knownFactor: "", startYear: "" })
                        )
                      }
                    >
                      {executiveHoldings.map((h) => (
                        <ExecutiveHoldingRow
                          key={h.id}
                          holding={h}
                          showRemove={executiveHoldings.length > 1}
                          onChange={(patch) => updateHolding(setExecutiveHoldings, h.id, patch)}
                          onRemove={() => removeHolding(setExecutiveHoldings, h.id)}
                          showErrors={showErrors}
                        />
                      ))}
                      <AddButton onClick={() => addHolding(setExecutiveHoldings, () => makeHolding({ id: newId(), factorMode: "known", knownFactor: "", startYear: "" }))} label={cfg.products.execInsurance.addMore} />
                    </ToggleCard>

                    {pensionFundOn && executiveOn && (
                      <div style={{ border: `1px solid ${BORDER}`, borderRadius: 10, padding: 14, background: "#FFFFFF" }}>
                        <Field label="לאיזו קופה מופקדים הכספים שלכם מדי חודש?">
                          <PillGroup
                            options={["קרן פנסיה", "ביטוח מנהלים"]}
                            value={
                              contributionDestination === "executive"
                                ? "ביטוח מנהלים"
                                : contributionDestination === "pension"
                                ? "קרן פנסיה"
                                : undefined
                            }
                            onChange={(v) => setContributionDestination(v === "ביטוח מנהלים" ? "executive" : "pension")}
                            error={showErrors && contributionDestination === ""}
                          />
                        </Field>
                      </div>
                    )}

                    <ToggleCard
                      icon={<Wallet size={16} />}
                      label={cfg.products.liquidSavings.title}
                      checked={savingsOn}
                      onToggle={() =>
                        toggleCategory(savingsOn, setSavingsOn, savingsHoldings, setSavingsHoldings, () =>
                          makeHolding({ id: newId(), managedBy: "" })
                        )
                      }
                    >
                      <p style={{ fontSize: 12, color: TEXT_FAINT, margin: "-4px 0 4px" }}>{cfg.products.liquidSavings.subLabel}</p>
                      {savingsHoldings.map((h) => (
                        <SavingsHoldingRow
                          key={h.id}
                          holding={h}
                          showRemove={savingsHoldings.length > 1}
                          onChange={(patch) => updateHolding(setSavingsHoldings, h.id, patch)}
                          onRemove={() => removeHolding(setSavingsHoldings, h.id)}
                          showErrors={showErrors}
                        />
                      ))}
                      <AddButton onClick={() => addHolding(setSavingsHoldings, () => makeHolding({ id: newId(), managedBy: "" }))} label={cfg.products.liquidSavings.addMore} />
                    </ToggleCard>

                    <ToggleCard
                      icon={<Banknote size={16} />}
                      label={cfg.products.cash.title}
                      checked={cashOn}
                      onToggle={() => setCashOn((v) => !v)}
                    >
                      <Field label={cfg.products.cash.amountLabel}>
                        <NumberInput
                          value={cashAmount}
                          onChange={(e) => setCashAmount(e.target.value)}
                          placeholder={cfg.products.cash.amountPlaceholder}
                          style={inputStyle}
                          error={showErrors && (cashAmount === "" || Number(cashAmount) < 0)}
                        />
                      </Field>
                    </ToggleCard>
                  </div>
                </div>

                <button
                  onClick={handleAttemptSubmit}
                  disabled={calculating}
                  className={shakeButton ? "shake" : ""}
                  style={{
                    marginTop: 4,
                    padding: "14px",
                    borderRadius: 999,
                    border: "none",
                    background: inputsValid && !calculating ? PURPLE : "#D6D8E2",
                    color: "#FFFFFF",
                    fontFamily: "'Rubik', sans-serif",
                    fontWeight: 700,
                    fontSize: 16,
                    cursor: inputsValid && !calculating ? "pointer" : "not-allowed",
                  }}
                >
                  {submitted ? "לעדכון החישוב" : cfg.baseInputs.submitBtn}
                </button>

                {!submitted && (
                  <div style={{ textAlign: "center" }}>
                    {!earlyLeadOpen ? (
                      <button
                        onClick={() => setEarlyLeadOpen(true)}
                        style={{
                          background: "transparent",
                          border: "none",
                          color: TEXT_MUTED,
                          fontFamily: "'Rubik', sans-serif",
                          fontSize: 13,
                          textDecoration: "underline",
                          cursor: "pointer",
                        }}
                      >
                        אין לכם זמן להזין נתונים? לחצו כאן ונבדוק עבורכם
                      </button>
                    ) : (
                      <div style={{ marginTop: 10, textAlign: "right" }}>
                        <LeadFormCard
                          leadName={leadName}
                          setLeadName={setLeadName}
                          leadPhone={leadPhone}
                          setLeadPhone={setLeadPhone}
                          leadConsent={leadConsent}
                          setLeadConsent={setLeadConsent}
                          leadError={leadError}
                          leadSubmitting={leadSubmitting}
                          leadSubmitted={leadSubmitted}
                          isLeadFormValid={isLeadFormValid}
                          handleLeadSubmit={handleLeadSubmit}
                          submitHover={submitHover}
                          setSubmitHover={setSubmitHover}
                        />
                      </div>
                    )}
                  </div>
                )}
              </>
            )}
          </div>
          </div>
        )}

        {(calculating || submitted) && (
          <button
            onClick={() => {
              setSubmitted(false);
              setCalculating(false);
            }}
            className="no-print"
            style={{
              display: "flex",
              alignItems: "center",
              gap: 6,
              background: "transparent",
              border: "none",
              color: PURPLE,
              fontFamily: "'Rubik', sans-serif",
              fontSize: 14,
              fontWeight: 500,
              cursor: "pointer",
              padding: "8px 0",
              marginBottom: 8,
            }}
          >
            <ChevronRight size={16} />
            חזרה לעריכת הנתונים
          </button>
        )}

        {calculating && (
          <div
            style={{
              marginTop: 20,
              background: CARD_BG,
              borderRadius: 12,
              padding: 24,
              boxShadow: "0 2px 16px rgba(30,42,92,0.08)",
            }}
          >
            <p style={{ fontSize: 14, color: TEXT_MUTED, marginBottom: 12, textAlign: "center" }}>
              {CALC_STEPS[calcStepIndex]}
            </p>
            <div style={{ height: 8, background: FIELD_BG, borderRadius: 999, overflow: "hidden" }}>
              <div
                style={{
                  height: "100%",
                  width: `${barWidth}%`,
                  background: barColor,
                  borderRadius: 999,
                  transition: `width ${CALC_ANIMATION_MS}ms ease, background-color ${CALC_ANIMATION_MS}ms ease`,
                }}
              />
            </div>
          </div>
        )}

        {submitted && result && (
          <div style={{ marginTop: 20, background: CARD_BG, borderRadius: 12, overflow: "hidden", boxShadow: "0 2px 16px rgba(30,42,92,0.08)" }}>
            <div
              style={{
                background: result.gapPercent >= GAP_MODERATE ? GRADIENT_ALERT : GRADIENT,
                padding: "16px 20px",
                color: "#FFFFFF",
                fontWeight: 700,
                fontSize: 17,
                textAlign: "center",
              }}
            >
              {heading}
            </div>

            <div style={{ padding: 22 }}>
              <div style={{ marginBottom: 20 }}>
                {(() => {
                  const severityColor =
                    result.gapPercent >= GAP_MODERATE
                      ? CRITICAL
                      : result.gapPercent >= 0
                      ? PURPLE
                      : POSITIVE;
                  const amountText = `₪${formatILSApprox(Math.abs(result.gapAmount))}`;
                  const isNegligibleGap = Math.abs(result.gapPercent) < GAP_NEGLIGIBLE;
                  const isDecrease = result.gapPercent > 0;
                  return (
                    <div
                      style={{
                        background: isDecrease ? "rgba(192,57,43,0.05)" : FIELD_BG,
                        border: `1px solid ${isDecrease ? CRITICAL_BORDER : BORDER}`,
                        borderRadius: 8,
                        padding: "14px 16px",
                      }}
                    >
                      <p style={{ fontSize: 17, color: NAVY, lineHeight: 1.7, margin: 0 }}>
                        השכר הנוכחי שלכם עומד על{" "}
                        <strong style={{ fontWeight: 700, color: NAVY }}>₪{formatILS(result.currentSalary)}</strong>{" "}
                        בחודש. לעומת זאת, ההכנסה החודשית שתעמוד לרשותכם בפרישה צפויה להיות{" "}
                        <strong style={{ fontWeight: 700, color: NAVY }}>כ-₪{formatILSApprox(result.monthlyIncome)}</strong>
                        {result.gapPercent > 0 && !isNegligibleGap ? " בלבד." : "."}
                      </p>
                      <p style={{ fontSize: 17, color: NAVY, lineHeight: 1.7, margin: "8px 0 0" }}>
                        {isNegligibleGap ? (
                          "זה אומר שרמת החיים שלכם צפויה להישמר כמעט בדיוק כפי שהיא כיום."
                        ) : (
                          <>
                            {isDecrease
                              ? "זה אומר שברגע שתפסיקו לעבוד, רמת החיים שלכם תיחתך בכ-"
                              : "זה אומר שברגע שתפסיקו לעבוד, התקציב החודשי שלכם יוכל לזנק בכ-"}
                            <strong style={{ fontSize: 22, fontWeight: 800, color: severityColor }}>{amountText}</strong>
                            {" "}מדי חודש.
                          </>
                        )}
                      </p>
                    </div>
                  );
                })()}
              </div>

              {(() => {
                noteCardRefs.current = [];
                return null;
              })()}

              {visibleNotes.length > 0 && (
                <div style={{ marginBottom: 20 }}>
                  <h3 style={{ fontSize: 16, fontWeight: 700, color: NAVY, margin: "0 0 10px" }}>
                    מה הנתונים שלכם מספרים לנו:
                  </h3>
                  <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                    {visibleNotes.map((note, i) => (
                      <div key={i} data-card-index={i} ref={(el) => (noteCardRefs.current[i] = el)}>
                        <NoteCard note={note} startDelay={i * 400} />
                      </div>
                    ))}
                  </div>
                </div>
              )}

              {(() => {
                  const dreamBullets = [];
                  if (result.gapPercent > 0 && result.hasExplicitExposureData) {
                    dreamBullets.push(
                      <>
                        תוספת של כ-
                        <strong style={{ fontWeight: 800 }}>
                          ₪{formatILSApprox(Math.max(result.monthlyAtBenchmark - result.monthlyIncome, 0))}
                        </strong>{" "}
                        לקצבה שלכם מדי חודש.
                      </>
                    );
                  }
                  if (result.capitalGap > 0) {
                    const monthlyAddition = Math.max(result.monthlyAtBenchmark - result.monthlyIncome, 0);
                    const pensionBulletShown = result.gapPercent > 0 && result.hasExplicitExposureData;
                    dreamBullets.push(
                      <>
                        פוטנציאל לעוד כ-
                        <strong style={{ fontWeight: 800 }}>₪{formatILSApprox(result.capitalGap)}</strong> שתוכלו לצבור עד
                        הפרישה
                        {!pensionBulletShown && (
                          <>
                            {" "}(שיגדילו את הקצבה שלכם בכ-
                            <strong style={{ fontWeight: 800 }}>₪{formatILSApprox(monthlyAddition)}</strong> נוספים כל
                            חודש!)
                          </>
                        )}
                        , וכרגע הפוטנציאל מתפספס בגלל ניהול לא מותאם.
                      </>
                    );
                  }
                  if (result.earlyRetirementAge !== null) {
                    dreamBullets.push(
                      <>
                        אפשרות אמיתית לפרישה מוקדמת כבר בגיל{" "}
                        <strong style={{ fontWeight: 800 }}>{result.earlyRetirementAge}</strong>.
                      </>
                    );
                  }
                  if (dreamBullets.length === 0) return null;
                  return (
                    <div
                      style={{
                        background: "rgba(46,125,79,0.08)",
                        border: `1.5px solid ${POSITIVE_BORDER}`,
                        borderRadius: 12,
                        padding: "18px 16px",
                        marginBottom: 20,
                      }}
                    >
                      <h3 style={{ fontSize: 16, fontWeight: 700, color: NAVY, margin: "0 0 12px" }}>
                        {result.isGreenScenario
                          ? "אתם בדרך הנכונה, אבל אפשר למקסם את הפוטנציאל עוד יותר:"
                          : "אבל זה לא חייב להיות ככה. תכנון מותאם אישית יכול לשנות את התמונה:"}
                      </h3>
                      <div style={{ display: "flex", flexDirection: "column", gap: 10 }}>
                        {dreamBullets.map((bullet, i) => (
                          <div key={i} style={{ display: "flex", alignItems: "flex-start", gap: 8 }}>
                            <Sparkles size={18} color={POSITIVE} style={{ flexShrink: 0, marginTop: 2 }} />
                            <p style={{ fontSize: 15, color: NAVY, lineHeight: 1.6, margin: 0 }}>{bullet}</p>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })()}

              {reachedEnd && (
                <div>
                  <LeadFormCard
                    leadName={leadName}
                    setLeadName={setLeadName}
                    leadPhone={leadPhone}
                    setLeadPhone={setLeadPhone}
                    leadConsent={leadConsent}
                    setLeadConsent={setLeadConsent}
                    leadError={leadError}
                    leadSubmitting={leadSubmitting}
                    leadSubmitted={leadSubmitted}
                    isLeadFormValid={isLeadFormValid}
                    handleLeadSubmit={handleLeadSubmit}
                    submitHover={submitHover}
                    setSubmitHover={setSubmitHover}
                  />
                </div>
              )}

              {/* Legal Disclaimer */}
              <div style={{ padding: "16px", background: "rgba(110, 116, 136, 0.05)", borderRadius: 8, marginBottom: 24, border: `1px solid ${BORDER}` }}>
                <p style={{ fontSize: 12, color: TEXT_MUTED, lineHeight: 1.5, margin: 0, textAlign: "justify" }}>
                  <strong>הבהרה משפטית:</strong> התוצאות וההערות המוצגות במחשבון הן הערכה כללית ואוטומטית בלבד, המבוססת על הנתונים שהזנתם ועל הנחות יסוד ממוצעות שאינן מובטחות. המידע <strong>אינו מהווה ייעוץ פנסיוני, ייעוץ השקעות או ייעוץ מס</strong> המותאם לנתוניו וצרכיו האישיים של המשתמש, ואינו תחליף לבחינה מקצועית. השירות ניתן על ידי <strong>אפקטיב פיננסים ופרישה - מבית רינג סוכנות לביטוח בע״מ (ח.פ 517031928)</strong>, הפועלת כסוכנות ביטוח העוסקת בשיווק פנסיוני (ולא בייעוץ) ולה זיקה למוצרים פנסיוניים. אין לבצע פעולות פיננסיות על בסיס נתונים אלו ללא התייעצות עם בעל רישיון. <a href="/calculator-terms" target="_blank" style={{ color: TEXT_MUTED, textDecoration: "underline" }}>לפירוט ההנחות ותנאי השימוש המלאים</a>.
                </p>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function NumberInput({ value, onChange, placeholder, style, error }) {
  return (
    <input
      type="number"
      value={value}
      onChange={onChange}
      placeholder={placeholder}
      style={error ? { ...style, border: "1.5px solid #C0392B" } : style}
      onWheel={(e) => e.target.blur()}
      onKeyDown={(e) => {
        if (e.key === "ArrowUp" || e.key === "ArrowDown") e.preventDefault();
      }}
      data-error-field={error ? "true" : undefined}
    />
  );
}

function Field({ label, children }) {
  return (
    <label style={{ display: "flex", flexDirection: "column", gap: 6 }}>
      <span style={{ fontSize: 13, color: NAVY, fontWeight: 500 }}>{label}</span>
      {children}
    </label>
  );
}

function PillButton({ active, onClick, children }) {
  return (
    <button
      onClick={onClick}
      style={{
        padding: "10px 12px",
        borderRadius: 999,
        border: active ? `1.5px solid ${PURPLE}` : `1px solid ${BORDER}`,
        background: active ? PURPLE_SOFT : FIELD_BG,
        color: active ? PURPLE : TEXT_MUTED,
        fontFamily: "'Rubik', sans-serif",
        fontWeight: 500,
        fontSize: 13,
        cursor: "pointer",
        flex: "1 1 auto",
      }}
    >
      {children}
    </button>
  );
}

function PillGroup({ options, value, onChange, error }) {
  return (
    <div
      style={{
        display: "flex",
        flexWrap: "wrap",
        gap: 8,
        padding: error ? 4 : 0,
        border: error ? "1.5px solid #C0392B" : "none",
        borderRadius: error ? 12 : 0,
      }}
      data-error-field={error ? "true" : undefined}
    >
      {options.map((opt) => (
        <PillButton key={opt} active={value === opt} onClick={() => onChange(opt)}>
          {opt}
        </PillButton>
      ))}
    </div>
  );
}

function ToggleCard({ icon, label, checked, onToggle, children }) {
  return (
    <div style={{ border: checked ? `1.5px solid ${PURPLE}` : `1px solid ${BORDER}`, borderRadius: 10, overflow: "hidden" }}>
      <button
        onClick={onToggle}
        style={{
          width: "100%",
          display: "flex",
          alignItems: "center",
          gap: 10,
          padding: "12px 14px",
          background: checked ? PURPLE_SOFT : "#FFFFFF",
          border: "none",
          cursor: "pointer",
          textAlign: "right",
        }}
      >
        <div
          style={{
            width: 20,
            height: 20,
            borderRadius: 6,
            border: checked ? "none" : `1.5px solid ${BORDER}`,
            background: checked ? PURPLE : "transparent",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            flexShrink: 0,
          }}
        >
          {checked && <Check size={14} color="#FFFFFF" />}
        </div>
        <span style={{ color: checked ? PURPLE : TEXT_MUTED }}>{icon}</span>
        <span style={{ fontSize: 14, color: NAVY, fontWeight: 500 }}>{label}</span>
      </button>
      {checked && <div style={{ padding: 14, display: "flex", flexDirection: "column", gap: 10, background: "#FFFFFF" }}>{children}</div>}
    </div>
  );
}

function HoldingCard({ children, onRemove, showRemove }) {
  return (
    <div style={{ background: FIELD_BG, borderRadius: 8, padding: 12, display: "flex", flexDirection: "column", gap: 10, position: "relative" }}>
      {showRemove && (
        <button
          onClick={onRemove}
          aria-label="הסרת רכיב"
          style={{ position: "absolute", top: 8, left: 8, background: "transparent", border: "none", color: TEXT_FAINT, cursor: "pointer", padding: 2 }}
        >
          <X size={16} />
        </button>
      )}
      {children}
    </div>
  );
}

function AddButton({ onClick, label }) {
  return (
    <button
      onClick={onClick}
      style={{
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        gap: 6,
        background: "transparent",
        border: `1px dashed ${BORDER}`,
        borderRadius: 8,
        padding: "8px",
        color: TEXT_MUTED,
        fontFamily: "'Rubik', sans-serif",
        fontSize: 13,
        cursor: "pointer",
      }}
    >
      <Plus size={14} />
      {label}
    </button>
  );
}

function RiskExposureFields({ holding, onChange, showErrors }) {
  const [showExposure, setShowExposure] = useState(holding.exposure !== "");
  return (
    <>
      <Field label={cfg.products.riskLabel}>
        <PillGroup
          options={RISK_LEVELS.map((r) => r.label)}
          value={RISK_LEVELS.find((r) => r.id === holding.risk)?.label}
          onChange={(label) => onChange({ risk: RISK_LEVELS.find((r) => r.label === label).id })}
          error={showErrors && holding.risk === ""}
        />
      </Field>
      {showExposure ? (
        <Field label={cfg.products.exposurePlaceholder}>
          <div style={{ display: "flex", gap: 8, alignItems: "center" }}>
            <div style={{ flex: 1 }}>
              <NumberInput value={holding.exposure} onChange={(e) => onChange({ exposure: e.target.value })} placeholder="לדוגמה: 60" style={inputStyle} />
            </div>
            <button
              onClick={() => {
                onChange({ exposure: "" });
                setShowExposure(false);
              }}
              aria-label="הסתרה וחזרה לברירת המחדל"
              style={{ background: "transparent", border: "none", color: TEXT_FAINT, cursor: "pointer", padding: 4, flexShrink: 0 }}
            >
              <X size={16} />
            </button>
          </div>
        </Field>
      ) : (
        <button
          onClick={() => setShowExposure(true)}
          style={{ alignSelf: "flex-start", background: FIELD_BG, border: `1px solid ${BORDER}`, borderRadius: 999, color: PURPLE, fontFamily: "'Rubik', sans-serif", fontWeight: 500, fontSize: 13, cursor: "pointer", padding: "8px 14px" }}
        >
          {cfg.products.exposureToggle}
        </button>
      )}
    </>
  );
}

function FundHoldingRow({ holding, onChange, onRemove, showRemove, showErrors }) {
  return (
    <HoldingCard onRemove={onRemove} showRemove={showRemove}>
      <Field label={cfg.products.pension.amountLabel}>
        <NumberInput
          value={holding.amount}
          onChange={(e) => onChange({ amount: e.target.value })}
          placeholder={cfg.products.pension.amountPlaceholder}
          style={inputStyle}
          error={showErrors && holding.amount === ""}
        />
      </Field>
      <RiskExposureFields holding={holding} onChange={onChange} showErrors={showErrors} />
    </HoldingCard>
  );
}

function ExecutiveHoldingRow({ holding, onChange, onRemove, showRemove, showErrors }) {
  const factorMode = holding.factorMode === "unknown" ? "unknown" : "known";
  return (
    <HoldingCard onRemove={onRemove} showRemove={showRemove}>
      <Field label={cfg.products.execInsurance.amountLabel}>
        <NumberInput
          value={holding.amount}
          onChange={(e) => onChange({ amount: e.target.value })}
          placeholder={cfg.products.execInsurance.amountPlaceholder}
          style={inputStyle}
          error={showErrors && holding.amount === ""}
        />
      </Field>
      <Field label={cfg.products.execInsurance.factorModeLabel}>
        <PillGroup
          options={[cfg.products.execInsurance.factorKnownOption, cfg.products.execInsurance.factorUnknownOption]}
          value={
            factorMode === "unknown"
              ? cfg.products.execInsurance.factorUnknownOption
              : cfg.products.execInsurance.factorKnownOption
          }
          onChange={(label) =>
            onChange({
              factorMode: label === cfg.products.execInsurance.factorUnknownOption ? "unknown" : "known",
            })
          }
        />
      </Field>
      {factorMode === "unknown" ? (
        <Field label={cfg.products.execInsurance.startYearLabel}>
          <NumberInput
            value={holding.startYear}
            onChange={(e) => onChange({ startYear: e.target.value })}
            placeholder={cfg.products.execInsurance.startYearPlaceholder}
            style={inputStyle}
            error={showErrors && (holding.startYear === "" || Number(holding.startYear) <= 0)}
          />
        </Field>
      ) : (
        <Field label={cfg.products.execInsurance.factorAmountLabel}>
          <NumberInput
            value={holding.knownFactor}
            onChange={(e) => onChange({ knownFactor: e.target.value })}
            placeholder={cfg.products.execInsurance.factorPlaceholder}
            style={inputStyle}
            error={showErrors && (holding.knownFactor === "" || Number(holding.knownFactor) <= 0)}
          />
        </Field>
      )}
      <RiskExposureFields holding={holding} onChange={onChange} showErrors={showErrors} />
    </HoldingCard>
  );
}

const SAVINGS_TYPES_WITH_MANAGER = ["תיק מניות מנוהל", "תיק השקעות עצמאי"];

function SavingsHoldingRow({ holding, onChange, onRemove, showRemove, showErrors }) {
  const showManagedField = SAVINGS_TYPES_WITH_MANAGER.includes(holding.assetLabel);
  return (
    <HoldingCard onRemove={onRemove} showRemove={showRemove}>
      <Field label={cfg.products.liquidSavings.assetTypeLabel}>
        <PillGroup options={cfg.products.liquidSavings.assetOptions} value={holding.assetLabel} onChange={(v) => onChange({ assetLabel: v })} />
      </Field>
      <Field label={cfg.products.liquidSavings.amountLabel}>
        <NumberInput
          value={holding.amount}
          onChange={(e) => onChange({ amount: e.target.value })}
          placeholder={cfg.products.liquidSavings.amountPlaceholder}
          style={inputStyle}
          error={showErrors && holding.amount === ""}
        />
      </Field>
      {showManagedField && (
        <Field label={cfg.products.liquidSavings.managedLabel}>
          <PillGroup
            options={cfg.products.liquidSavings.managedOptions}
            value={
              holding.managedBy === "bank"
                ? cfg.products.liquidSavings.managedOptions[1]
                : holding.managedBy === "independent"
                ? cfg.products.liquidSavings.managedOptions[0]
                : undefined
            }
            onChange={(v) => onChange({ managedBy: v === cfg.products.liquidSavings.managedOptions[1] ? "bank" : "independent" })}
            error={showErrors && holding.managedBy === ""}
          />
        </Field>
      )}
      <RiskExposureFields holding={holding} onChange={onChange} showErrors={showErrors} />
    </HoldingCard>
  );
}

function LeadFormCard({
  leadName,
  setLeadName,
  leadPhone,
  setLeadPhone,
  leadConsent,
  setLeadConsent,
  leadError,
  leadSubmitting,
  leadSubmitted,
  isLeadFormValid,
  handleLeadSubmit,
  submitHover,
  setSubmitHover,
}) {
  // Honeypot spam protection: a hidden field only a bot would fill in.
  const [honeypot, setHoneypot] = useState("");

  if (leadSubmitted) {
    return (
      <div style={{ background: FIELD_BG, borderRadius: 8, padding: 16, border: `1px solid ${POSITIVE_BORDER}` }}>
        <p style={{ fontSize: 15, fontWeight: 700, color: "#1E5E3A", margin: "0 0 6px" }}>{cfg.leadForm.successTitle}</p>
        <p style={{ fontSize: 14, color: "#5E6675", lineHeight: 1.6, margin: 0 }}>{cfg.leadForm.successBody}</p>
      </div>
    );
  }
  return (
    <div
      style={{
        background: "#FFFFFF",
        border: `1.5px solid ${PURPLE}`,
        borderRadius: 12,
        boxShadow: "0 4px 20px rgba(30, 42, 92, 0.08)",
        padding: "24px 20px",
        display: "flex",
        flexDirection: "column",
        gap: 12,
      }}
    >
      <div>
        <h3 style={{ fontSize: 19, fontWeight: 700, color: NAVY, margin: "0 0 8px" }}>{cfg.leadForm.title}</h3>
        <p style={{ fontSize: 14, color: "#5E6675", lineHeight: 1.6, margin: 0 }}>{cfg.leadForm.subtitle}</p>
      </div>
      <input type="text" value={leadName} onChange={(e) => setLeadName(e.target.value)} placeholder={cfg.leadForm.nameField} style={inputStyle} />
      <input type="tel" value={leadPhone} onChange={(e) => setLeadPhone(e.target.value)} placeholder={cfg.leadForm.phoneField} style={inputStyle} />

      <div style={{ position: "absolute", opacity: 0, top: -9999, left: -9999 }} aria-hidden="true">
        <input
          type="text"
          name="email_verify"
          tabIndex="-1"
          autoComplete="off"
          value={honeypot}
          onChange={(e) => setHoneypot(e.target.value)}
        />
      </div>

      <label style={{ display: "flex", alignItems: "flex-start", gap: 8, cursor: "pointer" }}>
        <input
          type="checkbox"
          checked={leadConsent}
          onChange={(e) => setLeadConsent(e.target.checked)}
          style={{ accentColor: PURPLE, marginTop: 2, flexShrink: 0 }}
        />
        <span style={{ fontSize: 12, color: TEXT_MUTED, lineHeight: 1.4 }}>
          אני מאשר/ת למסור את הפרטים והנתונים הפיננסיים שהזנתי לצורך יצירת קשר ותיאום שיחת מיפוי פנסיוני, בהתאם ל<a href="/calculator-terms" target="_blank" style={{ color: PURPLE, textDecoration: "underline" }}>תנאי השימוש ומדיניות הפרטיות</a>.
        </span>
      </label>

      {leadError && (
        <p style={{ fontSize: 12, color: CRITICAL, margin: 0 }}>הייתה תקלה קטנה בשליחת הפרטים. אנא נסו שוב.</p>
      )}

      <button
        onClick={() => handleLeadSubmit(honeypot)}
        disabled={!isLeadFormValid || leadSubmitting}
        onMouseEnter={() => setSubmitHover(true)}
        onMouseLeave={() => setSubmitHover(false)}
        style={{
          width: "100%",
          padding: "15px",
          borderRadius: 999,
          border: "none",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          gap: 8,
          background: !isLeadFormValid ? "#D6D8E2" : submitHover ? "#174A2E" : "#1E5E3A",
          color: !isLeadFormValid ? "#8F94A6" : "#FFFFFF",
          fontFamily: "'Rubik', sans-serif",
          fontWeight: 700,
          fontSize: 16,
          cursor: !isLeadFormValid ? "not-allowed" : "pointer",
        }}
      >
        {leadSubmitting && <Loader2 size={18} className="spin" />}
        {cfg.leadForm.submitBtn}
      </button>
    </div>
  );
}

function StatBox({ icon, label, value }) {
  return (
    <div style={{ flex: 1, background: FIELD_BG, borderRadius: 8, padding: "12px 14px", display: "flex", flexDirection: "column", gap: 6 }}>
      <div style={{ display: "flex", alignItems: "center", gap: 6 }}>
        {icon}
        <span style={{ fontSize: 12, color: TEXT_MUTED }}>{label}</span>
      </div>
      <span style={{ fontSize: 20, fontWeight: 700, color: NAVY }}>{value}</span>
    </div>
  );
}

function NoteCard({ note, startDelay = 0 }) {
  const solidColor = note.type === "critical" ? CRITICAL : note.type === "positive" ? POSITIVE : WARNING_TEXT;
  const borderColor = note.type === "critical" ? CRITICAL_BORDER : note.type === "positive" ? POSITIVE_BORDER : WARNING_BORDER;
  const bgColor = note.type === "critical" ? "rgba(192,57,43,0.05)" : note.type === "positive" ? "rgba(46,125,79,0.05)" : FIELD_BG;

  return (
    <div
      className="note-fade-in"
      style={{
        background: bgColor,
        borderRadius: 12,
        padding: "20px 16px",
        border: `1px solid ${borderColor}`,
        animationDelay: `${startDelay}ms`,
      }}
    >
      <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 12 }}>
        {note.icon}
        <span style={{ fontSize: 13, fontWeight: 700, color: TEXT_MUTED }}>{note.title}</span>
      </div>

      {note.bigNumber && (
        <div style={{ fontSize: 40, fontWeight: 800, color: solidColor, lineHeight: 1, marginBottom: 12 }}>
          {note.bigNumber}
        </div>
      )}

      <p style={{ fontSize: 15, color: NAVY, lineHeight: 1.6, margin: 0 }}>{note.text}</p>
    </div>
  );
}

const inputStyle = {
  width: "100%",
  boxSizing: "border-box",
  background: FIELD_BG,
  border: `1px solid ${BORDER}`,
  borderRadius: 8,
  padding: "10px 12px",
  color: NAVY,
  fontFamily: "'Rubik', sans-serif",
  fontSize: 15,
  outline: "none",
};
